<?php require_once __DIR__.'/../app/bootstrap.php'; if(!empty($_SESSION['admin_id'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$u=trim($_POST['username']??'');$p=$_POST['password']??'';$st=$pdo->prepare('SELECT id,username,password_hash FROM admins WHERE username=? LIMIT 1');$st->execute([$u]);$a=$st->fetch();if($a && password_verify($p,$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_username']=$a['username'];header('Location: index.php');exit;} $error='ইউজারনেম অথবা পাসওয়ার্ড সঠিক নয়।';} ?>
